from common import *
inventory=json.loads((OUT/'stage2-release-inventory.json').read_text())['tests']
plans=[
 ('iron-corpus','ANNO_IRON_CORPUS','1','iron mine: no fallback on the original scenes','iron_mine_test.cpp:722','Explicit ActorFreeComponent/import-only, 300 advance(100) calls per loaded scene. Asserts loaded > 0 and fallbacks == 0; initialization result and advance fault are not asserted; does not prove all 50 gameplay imports.'),
 ('iron-survey','ANNO_IRON_SURVEY','1','iron mine: site survey','iron_mine_test.cpp:268','Setup/world advances require no fault and construction eligibility is required; site locations/counts are printed, no site-count or latency assertion.'),
 ('progression-ship','ANNO_PROGRESSION_GAPS','1','progression gaps N: ship-start settlement','founding_assets_test.cpp:5317','Public sail/found/unload/build/road setup asserted. 300 advance(1000), no fault each. Asserts zero houses and clean invariants; prints stocks and exhaustion, no upgrade requirement.'),
 ('progression-towns','ANNO_PROGRESSION_GAPS','1','progression gaps N: endless02 and S01_07_01','population_live_canary_test.cpp:1650','Two existing component scenario specs, script INIT required if pending, 3000 advance(100), no fault each; rules and clean invariants asserted; reports needs/producers/population/accounts/stocks, no upgrade requirement.'),
 ('progression-probe','ANNO_PROGRESSION_PROBE','1','progression K3: probe of the first upgrade tick','population_progression_test.cpp:346','Public real-house setup asserted, Session::advance_to requires no fault each 100 ms. Prints first walker/transition; does not require an upgrade or assert its timing.'),
 ('supply-leather','ANNO_SIM_SUPPLY_SCALE','1','synthetic mechanics fixture: Release scale','leather_fixture_test.cpp:521','Synthetic workloads K=0,8,16,32, 100000 ticks; setup, no-fault advances, unaccounted hides/made/loaded zero asserted. Actual built counts/times printed, not performance guarantees.'),
 ('supply-farm','ANNO_SIM_SUPPLY_SCALE','1','resilience: harvest search work against unrelated farms','small_farm_resilience_test.cpp:735;417','Synthetic K=0,7,14,21 unrelated farms; World::create required, 8000 advance(100) each = 400000 ticks. This opt-in only prints deterministic counters/wall time; no no-fault/invariant/counter assertion in run_unrelated.'),
 ('transport','ANNO_SIM_TRANSPORT_STATS','1','transport search statistics','scenario_test.cpp:947','Explicit actor-free load of S01_07_01 and single36; requires parse and World::create, not no-fault/invariants or movement success. 3000 advance(100)=150000 ticks; prints snapshots at 0,30000,150000 and run counters/frontier.'),
 ('nav','ANNO_SIM_NAV_SCALE',str(OUT/'nav-scale'),'nav scale measurements','nav_scale_test.cpp:388;203;286','Synthetic 16 configs with nav and idle = 32 runs. Requires valid world, clean start/end invariants, public move admission, locality quotas/index rules, equal work/delays across unrelated F/I, artifact write success. Latency metrics only printed/written, not bounded by assertions.'),
 ('play','ANNO_PLAY_LIVE_TIMING','1','play: ms per 100 ms turn','app/tests/play_test.cpp:434','Requires Trade file, load_play success, runner step_ms == 10. Four map/profile 1000-turn timing samples; no latency/output or no-fault assertion. Despite test name, actual step is 10 ms; p50/p95 are measurements only.')]
rows=[]
for name,var,value,needle,source,scope in plans:
 matches=[t for t in inventory if needle in t['name']];assert len(matches)==1,(name,len(matches))
 rows.append({'id':name,'variable':var,'value':value,'test':matches[0]['name'],'source':source,'assertion_scope':scope,'release':True,'asan':name in ('supply-leather','supply-farm','transport')})
save(OUT/'stage4-preflight.json',{'read_before_execution':stamp(),'source':freeze(),'cases':rows,'rss_scope':'/usr/bin/time -l reported maximum resident set size; child maximum, not sum of simultaneous descendants.'})
